import React, { useEffect, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useIntl } from 'react-intl';
import { VictoryArea, VictoryChart, VictoryAxis } from 'victory';
import { fetchFoundVsClosedTimeline } from 'Screens/Contextualization/Dashboard/actions/Actions';
import { selectFoundVsClosedTimeline, selectIsLoadingState } from 'store/Dashboard/selectors';
import SpinnerComponent from 'Common/Components/SpinnerContainer';
import colors from 'Styles/colors';
import {
  Wrapper,
  ContentRow,
  ChartArea,
  SummaryCards,
  SummaryCard,
  SummaryLabel,
  SummaryCount,
  SummaryDelta,
  Empty,
  SummaryBottomLabel,
  SummaryLabelContainer
} from './styled';
import { Title, TitleContainer, TitleWrapper } from '../common/styled';

const FOUND_COLOR = colors.orange2;
const CLOSED_COLOR = colors.green1;

const FoundVsClosed = () => {
  const dispatch = useDispatch();
  const intl = useIntl();

  const timeline = useSelector(selectFoundVsClosedTimeline);
  const isLoading = useSelector((state) => selectIsLoadingState(state, 'foundVsClosedTimeline'));

  const translations = {
    title: intl.formatMessage({ id: 'dashboard.widgets.foundVsClosed.title' }),
    found: intl.formatMessage({ id: 'dashboard.widgets.foundVsClosed.labels.found' }),
    closed: intl.formatMessage({ id: 'dashboard.widgets.foundVsClosed.labels.closed' }),
    foundText: '7d - cumulative',
    closedText: 'by consultant + client'
  };

  useEffect(() => {
    dispatch(fetchFoundVsClosedTimeline(15));
  }, [dispatch]);

  const { foundData, closedData, foundTotal, closedTotal, foundDelta, closedDelta, tickValues, tickFormat } = useMemo(() => {
    if (!timeline || timeline.length === 0) {
      return { foundData: [], closedData: [], foundTotal: 0, closedTotal: 0, foundDelta: 0, closedDelta: 0, tickValues: [], tickFormat: () => '' };
    }

    const foundData = timeline.map((item, idx) => ({ x: idx, y: item.found_count }));
    const closedData = timeline.map((item, idx) => ({ x: idx, y: item.closed_count }));

    const foundTotal = timeline.reduce((sum, item) => sum + item.found_count, 0);
    const closedTotal = timeline.reduce((sum, item) => sum + item.closed_count, 0);

    const half = Math.floor(timeline.length / 2);
    const foundDelta = timeline.slice(half).reduce((s, i) => s + i.found_count, 0) -
      timeline.slice(0, half).reduce((s, i) => s + i.found_count, 0);
    const closedDelta = timeline.slice(half).reduce((s, i) => s + i.closed_count, 0) -
      timeline.slice(0, half).reduce((s, i) => s + i.closed_count, 0);

    const last = timeline.length - 1;
    const tickValues = [0, Math.floor(last / 3), Math.floor((last * 2) / 3), last];

    const tickFormat = (t) => {
      if (t === last) return 'TODAY';
      const item = timeline[t];
      if (!item) return '';
      const d = new Date(item.date);
      if (t === 0) return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }).toUpperCase();
      return String(d.getDate());
    };

    return { foundData, closedData, foundTotal, closedTotal, foundDelta, closedDelta, tickValues, tickFormat };
  }, [timeline]);

  if (isLoading) return <SpinnerComponent height="200px" />;

  if (!timeline || timeline.length === 0) {
    return (
      <Wrapper>
        <TitleWrapper>
          <TitleContainer><Title>{translations.title}</Title></TitleContainer>
        </TitleWrapper>
        <Empty>No data available</Empty>
      </Wrapper>
    );
  }

  return (
    <Wrapper>
      <svg width="0" height="0" style={ { position: 'absolute' } }>
        <defs>
          <linearGradient id="fvcFoundGradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={ FOUND_COLOR } stopOpacity="0.35" />
            <stop offset="100%" stopColor={ FOUND_COLOR } stopOpacity="0.03" />
          </linearGradient>
          <linearGradient id="fvcClosedGradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={ CLOSED_COLOR } stopOpacity="0.35" />
            <stop offset="100%" stopColor={ CLOSED_COLOR } stopOpacity="0.03" />
          </linearGradient>
        </defs>
      </svg>

      <TitleWrapper>
        <TitleContainer>
          <Title>{translations.title}</Title>
        </TitleContainer>
      </TitleWrapper>

      <ContentRow>
        <ChartArea>
          <VictoryChart
            height={ 160 }
            padding={ { top: 10, bottom: 28, left: 8, right: 8 } }
          >
            <VictoryAxis
              tickValues={ tickValues }
              tickFormat={ tickFormat }
              style={ {
                axis: { stroke: 'transparent' },
                ticks: { stroke: 'transparent' },
                tickLabels: { fontSize: 7, fill: '#aaa' },
                grid: { stroke: 'transparent' }
              } }
            />
            <VictoryAxis
              dependentAxis
              style={ {
                axis: { stroke: 'transparent' },
                ticks: { stroke: 'transparent' },
                tickLabels: { fill: 'transparent' },
                grid: { stroke: 'rgba(180,180,180,0.15)', strokeDasharray: '4,4' }
              } }
            />
            <VictoryArea
              data={ foundData }
              interpolation="natural"
              style={ {
                data: {
                  stroke: FOUND_COLOR,
                  strokeWidth: 2,
                  fill: 'url(#fvcFoundGradient)'
                }
              } }
            />
            <VictoryArea
              data={ closedData }
              interpolation="natural"
              style={ {
                data: {
                  stroke: CLOSED_COLOR,
                  strokeWidth: 2,
                  strokeDasharray: '5,3',
                  fill: 'url(#fvcClosedGradient)'
                }
              } }
            />
          </VictoryChart>
        </ChartArea>

        <SummaryCards>
          <SummaryCard $color={ FOUND_COLOR }>
           <SummaryLabelContainer>
              <SummaryLabel>{translations.found}</SummaryLabel>
              <SummaryBottomLabel>{translations.foundText}</SummaryBottomLabel>
           </SummaryLabelContainer>
            <SummaryCount>{foundTotal}</SummaryCount>
            <SummaryDelta $positive={ foundDelta >= 0 }>
              {foundDelta >= 0 ? '▲' : '▼'} {foundDelta >= 0 ? `+${foundDelta}` : foundDelta}
            </SummaryDelta>
          </SummaryCard>
          <SummaryCard $color={ CLOSED_COLOR }>
            <SummaryLabelContainer>
              <SummaryLabel>{translations.closed}</SummaryLabel>
              <SummaryBottomLabel>{translations.closedText}</SummaryBottomLabel>
            </SummaryLabelContainer>
            <SummaryCount>{closedTotal}</SummaryCount>
            <SummaryDelta $positive={ closedDelta >= 0 }>
              {closedDelta >= 0 ? '▲' : '▼'} {closedDelta >= 0 ? `+${closedDelta}` : closedDelta}
            </SummaryDelta>
          </SummaryCard>
        </SummaryCards>
      </ContentRow>
    </Wrapper>
  );
};

export default FoundVsClosed;
